<?php
declare(strict_types=1);namespace Joomleague\Module\LatestResults\Site\Helper;defined('_JEXEC')or die;
use Joomla\CMS\Factory;use Joomla\Database\DatabaseInterface;use Joomla\Registry\Registry;use Joomleague\Component\Joomleague\Domain\Service\CrossProjectProgrammeReader;use Joomleague\Component\Joomleague\Site\Service\ProjectTemplateProvider;
final class LatestResultsHelper{/** @return array<string,mixed> */public function getResults(Registry$p):array{$app=Factory::getApplication();$app->bootComponent('com_joomleague');Factory::getLanguage()->load('com_joomleague',JPATH_SITE)||Factory::getLanguage()->load('com_joomleague',JPATH_SITE.'/components/com_joomleague');$levels=$app->getIdentity()?->getAuthorisedViewLevels()??[1];$db=Factory::getContainer()->get(DatabaseInterface::class);$now=Factory::getDate();$from=clone$now;$from->modify('-'.min(5000,max(1,(int)$p->get('days_before',365))).' days')->setTime(0,0);try{$items=(new CrossProjectProgrammeReader($db))->between($levels,$from->toUnix(),$now->toUnix(),max(0,(int)$p->get('sport_type_id',0)),max(0,(int)$p->get('club_id',0)),max(0,(int)$p->get('project_id',0)));}catch(\Throwable){return['error'=>'MOD_JOOMLEAGUE_LATEST_RESULTS_EMPTY'];}$items=array_values(array_filter($items,static fn(array$i):bool=>(bool)$i['played']));usort($items,static fn(array$a,array$b):int=>$b['timestamp']<=>$a['timestamp']?:$b['id']<=>$a['id']);$items=array_slice($items,0,min(50,max(1,(int)$p->get('limit',5))));if($items===[])return['error'=>'MOD_JOOMLEAGUE_LATEST_RESULTS_EMPTY'];$provider=new ProjectTemplateProvider($db);$templates=[];foreach($items as&$item){$id=(int)$item['project_id'];if(!isset($templates[$id]))try{$templates[$id]=$provider->supports($id,'results')?$provider->resolve($id,'results'):[];}catch(\Throwable){$templates[$id]=[];}$item['show_detail']=(bool)($templates[$id]['show_match_detail_button']??true);}unset($item);return['items'=>$items];}}
